import{_ as n,c as a,o as i,ae as o}from"./chunks/framework.BR0IJ75L.js";const u=JSON.parse('{"title":"🚀 Getting Started","description":"","frontmatter":{},"headers":[],"relativePath":"docs/nui/qs.md","filePath":"docs/nui/qs.md"}'),t={name:"docs/nui/qs.md"};function s(r,e,l,p,d,c){return i(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="🚀-getting-started" tabindex="-1">🚀 Getting Started <a class="header-anchor" href="#🚀-getting-started" aria-label="Permalink to &quot;🚀 Getting Started&quot;">​</a></h1><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>Neo UI Framework is for development and testing purposes. For production-grade deployment, refer to the latest Neo deployment from the <a href="https://github.com/NetApp/Innovation-Labs/" target="_blank" rel="noreferrer">NetApp Innovation Labs</a> repository.</p></div><h2 id="⚙️-neo-backend-running-externally" tabindex="-1">⚙️ Neo backend running externally <a class="header-anchor" href="#⚙️-neo-backend-running-externally" aria-label="Permalink to &quot;⚙️ Neo backend running externally&quot;">​</a></h2><p>When running the Neo backend externally, the following configuration needs to be considered:</p><h3 id="environment-variables-when-running-from-sources" tabindex="-1">Environment Variables when running from sources <a class="header-anchor" href="#environment-variables-when-running-from-sources" aria-label="Permalink to &quot;Environment Variables when running from sources&quot;">​</a></h3><p>The application uses Vite&#39;s environment variable system:</p><ul><li><code>VITE_API_BASE_URL</code> - Base URL for API requests (default: <code>/api</code>)</li></ul><h3 id="runtime-configuration-when-running-in-docker-podman" tabindex="-1">Runtime Configuration when running in docker/podman <a class="header-anchor" href="#runtime-configuration-when-running-in-docker-podman" aria-label="Permalink to &quot;Runtime Configuration when running in docker/podman&quot;">​</a></h3><p>For containerized deployments, configure the Neo API endpoint:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> NEO_API=http://neo-backend:8080</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neo-ui-framework</span></span></code></pre></div><p>The <code>entrypoint.sh</code> script injects this value into nginx configuration at runtime.</p><h2 id="from-source" tabindex="-1">From source <a class="header-anchor" href="#from-source" aria-label="Permalink to &quot;From source&quot;">​</a></h2><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>Node.js 20+ and npm 10+</li><li>Docker and Docker Compose (for containerized deployment)</li><li>Access to a NetApp Neo API instance</li><li>A running Neo v2.2.6 instance <a href="https://github.com/NetApp/Innovation-Labs/blob/main/netapp-neo/DEPLOY-V2.md" target="_blank" rel="noreferrer">Neo Quickstart</a></li></ul><ol><li><p>Clone the repository:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clone</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/NetApp/neo-ui-framework</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> neo-ui-framework</span></span></code></pre></div></li><li><p>Install dependencies:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span></span></code></pre></div></li><li><p>Run the dev server:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dev</span></span></code></pre></div></li></ol><p>The application will be available at <code>http://localhost:5173</code></p><p>The development proxy is configured in <code>vite.config.ts</code> to forward <code>/api</code> requests to your Neo API backend instance (default: <code>http://localhost:8081</code>).</p><h2 id="🐳-docker-deployment" tabindex="-1">🐳 Docker Deployment <a class="header-anchor" href="#🐳-docker-deployment" aria-label="Permalink to &quot;🐳 Docker Deployment&quot;">​</a></h2><div class="important custom-block github-alert"><p class="custom-block-title">IMPORTANT</p><p>While Podman can be used, the rootless nature does not allow Neo to mount SMB shares in the container. Either use Docker or run Podman in rootful using <code>sudo</code>.</p></div><h3 id="using-docker-compose" tabindex="-1">Using Docker Compose <a class="header-anchor" href="#using-docker-compose" aria-label="Permalink to &quot;Using Docker Compose&quot;">​</a></h3><p>This approach bundles both the Neo instance and UI together for an easer deployment.</p><p>The docker compose configuration runs three services:</p><ul><li><code>neo-smb</code>, a simple SMB server for testing purposes only</li><li><code>netapp-neo-ui</code>, the Neo UI framework</li><li><code>netapp-neo</code>, NetApp Neo instance. all running in a dedicated container network.</li></ul><p>The included <code>docker-compose.yml</code> provides a complete development stack:</p><pre><code>```bash\ndocker-compose up -d\n```\n</code></pre><p>This starts:</p><ul><li>a SMB server on port 445 that you access locally to add files to (doc, docx, ppt, pdf, ...)</li><li>the Neo UI on port 8080 with a preconfigured proxy for API requests to the Neo backend</li><li>the Neo backend</li></ul><p>Environment variables <strong>should be customized</strong> in <code>docker-compose.yml</code> or via a <code>.env</code> file as per <a href="https://github.com/NetApp/Innovation-Labs/blob/main/netapp-neo/DEPLOY-V2.md" target="_blank" rel="noreferrer">Neo Quickstart</a> to connect to your Microsoft GraphQL tenant and Copilot.</p>',28)])])}const k=n(t,[["render",s]]);export{u as __pageData,k as default};
